// From the GlassHome "Authentic Weather" widget (src/weather/weather-bg.ts), taken over unchanged.
/**
 * <weather-bg> Custom Web Component
 * Animated weather background for GlassHome / Home Assistant.
 *
 * Attributes:
 *   condition   – HA weather condition string (e.g. "sunny", "rainy")
 *   cloud-src   – URL of the cloud image
 *   is-night    – "true" | "false" | "auto" (auto = clock-based)
 *   overlay     – "true": draw ONLY the moving parts (rain, snow, hail, wind
 *                 leaves, lightning flash) over something else that already
 *                 paints the sky — no gradient, sun, moon, stars or clouds.
 */

export interface ConditionProfile {
  showSun?: boolean; showMoon?: boolean; forceNightScene?: boolean;
  cloudOpacity?: number; cloudOpacityDay?: number; cloudOpacityNight?: number;
  starsOpacity?: number; starsOpacityDay?: number; starsOpacityNight?: number;
  rainCount?: number; snowCount?: number; hailCount?: number; leavesCount?: number;
  thunder?: boolean;
  fogOpacity?: number; fogOpacityDay?: number; fogOpacityNight?: number;
  dayFilter?: string; dayFilterDay?: string; dayFilterNight?: string;
  cloudFilter?: string; cloudFilterDay?: string; cloudFilterNight?: string;
}

/** Original cloud PNG embedded as base64 — 320×307 RGBA, no external file needed. */
// prettier-ignore
// Soft cloud texture. Stored as WebP: the source PNG was RGBA but fully
// greyscale (R=G=B everywhere) with alpha capped at 128, so two channels
// were dead weight in a 112 KB base64 blob. WebP q90 keeps it visually
// identical (max composited error 2/255) at a third of the size.
export const CLOUD_PNG = "data:image/webp;base64,";

export const VALID = new Set([
  "clear-night","cloudy","fog","hail","lightning","lightning-rainy",
  "partlycloudy","pouring","rainy","snowy","snowy-rainy","sunny",
  "windy","windy-variant","exceptional",
]);

