// ── Moon phase SVG ───────────────────────────────────────────────────────────

/**
 * Builds one half of the phase boundary as an SVG arc path.
 *
 *   waxing=true,  f=0.2  → lit right crescent
 *   waxing=false, 1-f    → shadow complement (dark right crescent becomes dark left 80%)
 *
 * Shadow path = phasePath(!waxing, 1−f, …)
 */
export function phasePath(waxing: boolean, f: number, r: number, top: string, bot: string): string {
  if (f >= 1) return `M ${top} A ${r} ${r} 0 0 1 ${bot} A ${r} ${r} 0 0 1 ${top} Z`;
  if (f <= 0) return "";
  const tx = +(r * Math.abs(1 - 2 * f)).toFixed(2);
  if (Math.abs(f - 0.5) < 0.001) {
    return waxing
      ? `M ${top} A ${r} ${r} 0 0 1 ${bot} L ${top} Z`
      : `M ${top} A ${r} ${r} 0 0 0 ${bot} L ${top} Z`;
  }
  const sw1 = waxing ? 1 : 0;
  const sw2 = waxing ? (f < 0.5 ? 0 : 1) : (f < 0.5 ? 1 : 0);
  return `M ${top} A ${r} ${r} 0 0 ${sw1} ${bot} A ${tx} ${r} 0 0 ${sw2} ${top} Z`;
}

/**
 * Generates an inline SVG showing the correct lunar phase.
 * Gradient disc with selenographically-positioned mare ellipses.
 *
 * Phase fraction lookup (HA sensor.moon states → visual fractions):
 *   new_moon 0 · waxing_crescent 0.20 · first_quarter 0.50
 *   waxing_gibbous 0.80 · full_moon 1.00  (and mirror for waning)
 */
function buildMoonSVG(phase: string): string {
  const cx = 50, cy = 50, r = 44;
  const top = `${cx} ${cy - r}`, bot = `${cx} ${cy + r}`;

  const PHASES: Record<string, [boolean, number]> = {
    new_moon:        [true,  0],
    waxing_crescent: [true,  0.20],
    first_quarter:   [true,  0.50],
    waxing_gibbous:  [true,  0.80],
    full_moon:       [true,  1.00],
    waning_gibbous:  [false, 0.80],
    last_quarter:    [false, 0.50],
    waning_crescent: [false, 0.20],
  };

  const [waxing, f] = PHASES[phase] ?? [true, 1.0];
  const litPath = phasePath(waxing, f, r, top, bot);

  // Phase-accurate glow: 4 scaled copies of lit path, no SVG filter needed.
  const glow = (s: number, a: number) =>
    litPath
      ? `<path d="${litPath}" fill="rgba(255,250,215,${a})" transform="translate(50,50) scale(${s}) translate(-50,-50)"/>`
      : "";
  const glowLayers = glow(1.40, 0.10) + glow(1.25, 0.18) + glow(1.13, 0.30) + glow(1.05, 0.48);

  // Convert an ellipse to two arc sub-paths so it can be part of a compound <path>.
  // fill-rule="nonzero" (SVG default) means overlapping same-winding sub-paths
  // fill uniformly — no alpha compounding at intersections.
  const ep = (ex: number, ey: number, erx: number, ery: number) =>
    `M ${ex} ${ey - ery} A ${erx} ${ery} 0 0 1 ${ex} ${ey + ery} A ${erx} ${ery} 0 0 1 ${ex} ${ey - ery} Z`;

  // Selenographically-positioned maria, all in one <path> → single opacity, zero compounding.
  const marePath =
    ep(27, 26,  9, 13) + ep(22, 44, 12, 14) + ep(28, 62,  8, 10) + // Oceanus Procellarum
    ep(37, 30, 13, 11) +  // Mare Imbrium
    ep(62, 32,  9,  8) +  // Mare Serenitatis
    ep(68, 46, 10,  8) +  // Mare Tranquillitatis
    ep(74, 55,  8,  7) +  // Mare Fecunditatis
    ep(80, 37,  4,  5) +  // Mare Crisium (foreshortened)
    ep(43, 63,  8,  6) +  // Mare Nubium
    ep(30, 68,  6,  5) +  // Mare Humorum
    ep(55, 44,  4,  3) +  // Mare Vaporum
    ep(64, 23,  5,  4);   // Lacus Somniorum
  const mareElem  = `<path d="${marePath}" fill="rgb(160,170,185)" opacity="0.28"/>`;
  const platoElem = `<path d="${ep(38, 19, 3, 2)}" fill="rgb(72,82,102)" opacity="0.42"/>`;
  const tychoElem = `<circle cx="43" cy="70" r="2" fill="rgba(220,226,236,0.28)"/>`;

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" width="100%" height="100%" style="display:block;overflow:visible">
  <defs>
    <radialGradient id="mlit" cx="38%" cy="32%" r="72%">
      <stop offset="0%" stop-color="#f8f3e8"/>
      <stop offset="70%" stop-color="#dde5f2"/>
      <stop offset="100%" stop-color="#bcc8dc"/>
    </radialGradient>
    <clipPath id="mlc">${litPath ? `<path d="${litPath}"/>` : ""}</clipPath>
  </defs>
  <circle cx="${cx}" cy="${cy}" r="${r}" fill="#101a2e"/>
  ${glowLayers}
  ${litPath ? `<g clip-path="url(#mlc)">
    <circle cx="${cx}" cy="${cy}" r="${r}" fill="url(#mlit)"/>
    ${mareElem}${platoElem}${tychoElem}
  </g>` : ""}
  <circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="rgba(255,252,225,0.22)" stroke-width="2"/>
</svg>`;
}

// ── Web component ─────────────────────────────────────────────────────────────

class WeatherBgElement extends HTMLElement {
  static get observedAttributes() { return ["condition","cloud-src","is-night","transparent","moon-phase","colored-bg","compact","paused","overlay"]; }

  private _flashTimer: ReturnType<typeof setTimeout> | null = null;
  private _rendered = false;
  private _ro: ResizeObserver | null = null;
  private _lastH = 0;
  private _lastW = 0;

  private $bgDay!: HTMLElement; private $bgNight!: HTMLElement;
  private $stars!: HTMLElement; private $sun!: HTMLElement; private $moon!: HTMLElement;
  private $clouds!: HTMLElement; private $fogHaze!: HTMLElement;
  private $rain!: HTMLElement; private $snow!: HTMLElement;
  private $hail!: HTMLElement; private $wind!: HTMLElement;
  private $thunder!: HTMLElement; private $flash!: HTMLElement; private $sunglow!: HTMLElement; private $sunrays!: HTMLElement; private $motes!: HTMLElement;

  constructor() { super(); this.attachShadow({ mode: "open" }); }

  // the sealed engine (GlassHome 1.5 preview) gives custom elements no shadow root: nothing to draw into, so no animation, but no crash
  connectedCallback() { if (!this.shadowRoot) return; this.render(); }
  disconnectedCallback() { this.clearTimers(); this._ro?.disconnect(); this._ro = null; }
  attributeChangedCallback(name: string) {
    if (!this.isConnected || !this._rendered) return;
    // Pausing touches ONLY the lightning loop. applyState would rebuild every
    // particle, and this attribute flips each time the tile scrolls in or out.
    // The CSS particles need nothing here: :host([paused]) holds them in place.
    if (name === "paused") { this.syncLightning(); return; }
    if (name === "cloud-src") this.renderClouds();
    if (name === "moon-phase") this.renderMoon();
    this.applyState();
  }

  private get isPaused() { return this.getAttribute("paused") === "true"; }

  // The flash is a self-rescheduling JS timer, so no CSS rule can stop it —
  // it has to be cleared and restarted explicitly.
  private syncLightning() {
    this.clearTimers();
    const p = PROFILES[this.normalizeCondition(this.condition)] ?? PROFILES.cloudy;
    if (p.thunder) this.startLightning();
  }

  private clearTimers() {
    if (this._flashTimer) { clearTimeout(this._flashTimer); this._flashTimer = null; }
  }

  private get condition() { return (this.getAttribute("condition") || "cloudy").toLowerCase(); }
  private get cloudSrc()  {
    return this.getAttribute("cloud-src") || CLOUD_PNG;
  }
  private get isTransparent(): boolean {
    const v = this.getAttribute("transparent");
    return v !== null && v !== "false" && v !== "0";
  }
  private get isOverlay(): boolean {
    const v = this.getAttribute("overlay");
    return v !== null && v !== "false" && v !== "0";
  }
  private get isColoredBg(): boolean {
    const v = this.getAttribute("colored-bg");
    return v === null || v === "true" || v === "1";
  }
  private get forcedNight(): boolean | null {
    const v = this.getAttribute("is-night");
    if (!v || v === "" || v.toLowerCase() === "auto") return null;
    const l = v.toLowerCase();
    if (["1","true","yes","on","night","below_horizon"].includes(l)) return true;
    if (["0","false","no","off","day","above_horizon"].includes(l)) return false;
    return null;
  }

  private normalizeCondition(c: string) { return VALID.has(c) ? c : "cloudy"; }
  private isNightByClock() { const h = new Date().getHours(); return h < 6 || h >= 20; }

  private getVal(profile: ConditionProfile, key: string, night: boolean, fallback: number): number {
    const base = (profile as any)[key];
    if (base !== undefined) return base;
    const variant = (profile as any)[`${key}${night ? "Night" : "Day"}`];
    if (variant !== undefined) return variant;
    const opposite = (profile as any)[`${key}${night ? "Day" : "Night"}`];
    if (opposite !== undefined) return opposite;
    return fallback;
  }

  private getStr(profile: ConditionProfile, key: string, night: boolean): string | null {
    const base = (profile as any)[key];
    if (base !== undefined) return base;
    const variant = (profile as any)[`${key}${night ? "Night" : "Day"}`];
    if (variant !== undefined) return variant;
    const opposite = (profile as any)[`${key}${night ? "Day" : "Night"}`];
    return opposite ?? null;
  }

  private $(id: string) { return this.shadowRoot!.getElementById(id)!; }

  private render() {
    this.shadowRoot!.innerHTML = `<style>${SHADOW_CSS}</style>${HTML}`;
    this.$bgDay   = this.$("bgDay");   this.$bgNight = this.$("bgNight");
    this.$stars   = this.$("stars");   this.$sun     = this.$("sun");
    this.$moon    = this.$("moon");    this.$clouds  = this.$("clouds");
    this.$fogHaze = this.$("fogHaze"); this.$rain    = this.$("rain");
    this.$snow    = this.$("snow");    this.$hail    = this.$("hail");
    this.$wind    = this.$("wind");    this.$thunder = this.$("thunder");
    this.$flash   = this.$("flash");
    this.$sunglow = this.$("sunglow");
    this.$sunrays = this.$("sunrays");
    this.$motes = this.$("motes");
    this.renderClouds();
    this.renderStars();
    this.renderMoon();
    this._rendered = true;
    this.applyState();
    // Overlay rain sizes its streaks from the tile height, which is only known
    // after layout and changes with the tile — rebuild when it moves noticeably.
    if (this.isOverlay && typeof ResizeObserver !== "undefined") {
      this._ro?.disconnect();
      this._ro = new ResizeObserver(() => {
        const h = this.clientHeight, w = this.clientWidth;
        if (h > 0 && w > 0 && (Math.abs(h - this._lastH) / h > 0.06 || Math.abs(w - this._lastW) / w > 0.06)) { this._lastH = h; this._lastW = w; this.applyState(); }
      });
      this._ro.observe(this);
    }
  }

  private getCanvasSrc(): string { return CLOUD_PNG; }

  private renderClouds() {
    const src = this.cloudSrc;
    this.$clouds.innerHTML = "";
    delete this.$clouds.dataset.ov;   // overlay mode rebuilds its own set on the next applyState
    for (const cls of ["c1", "c2", "c3"]) {
      const img = document.createElement("img");
      img.className = `cloud-img ${cls}`;
      img.alt = "";
      img.src = src;
      // If the configured URL fails (e.g. /local/cloud.png doesn't exist),
      // fall back to the canvas-generated cloud immediately.
      img.onerror = () => {
        const fallback = this.getCanvasSrc();
        if (img.src !== fallback) img.src = fallback;
      };
      this.$clouds.appendChild(img);
    }
  }

  // Overlay mode sits on a picture that is cover-scaled into the tile (object-fit:
  // cover, focus 50 % / 62 %, source 1000 x 464). Everything that should follow
  // the SKY of that picture — clouds, the fade line, the stars — is placed in the
  // picture's own coordinates, not as a % of the tile: a tall narrow tile
  // magnifies the picture (its sky is then mostly above the tile's top edge) and a
  // low wide one shows it at width scale, so tile-relative numbers drifted apart.
  private pictureFrame() {
    const W = this.clientWidth || 600, H = this.clientHeight || 300;
    const Hp = Math.max(H, W * 0.464);              // picture height in px
    const off = (H - Hp) * 0.62;                     // its top edge relative to the tile (<= 0)
    return { W, H, Hp, off };
  }

  private renderStars() {
    const frag = document.createDocumentFragment();
    // Overlay mode: the sky is in the picture and the meadow must stay star-free,
    // so the stars are confined to the upper band and a few more of them twinkle.
    const overlay = this.isOverlay;
    const n = overlay ? 20 : 16;
    for (let i = 0; i < n; i++) {
      const s = document.createElement("span");
      const size = 0.8 + 1.8 * Math.random();
      const twinkle = overlay ? i % 2 === 0 : i % 3 === 0;
      s.className = twinkle ? "star twinkle" : "star";
      s.style.width  = `${size}px`;
      s.style.height = `${size}px`;
      s.style.left   = `${100 * Math.random()}%`;
      s.dataset.r = String(Math.random());
      s.style.top    = overlay ? "0px" : `${4 + 58 * Math.random()}%`;
      if (twinkle) {
        s.style.setProperty("--twinkle-speed", `${(1.8 + 2.8 * Math.random()) * (overlay ? 1.7 : 1)}s`);
        s.style.setProperty("--twinkle-delay", `${2.2 * Math.random()}s`);
      } else {
        s.style.opacity = `${0.25 + 0.65 * Math.random()}`;
      }
      frag.appendChild(s);
    }
    this.$stars.innerHTML = "";
    this.$stars.appendChild(frag);
  }

  private renderMoon() {
    const phase = this.getAttribute("moon-phase") || "full_moon";
    this.$moon.innerHTML = buildMoonSVG(phase);
  }

  // Overlay only: the front cloud layer and the slot for the balloon, added after the
  // back layer (#clouds) in the shadow root.
  private ensureFrontClouds(): HTMLElement {
    let el = this.shadowRoot!.getElementById("clouds-front");
    if (!el) {
      const slot = document.createElement("slot");
      slot.name = "mid";
      el = document.createElement("div");
      el.className = "clouds"; el.id = "clouds-front";
      this.$clouds.after(slot, el);
    }
    return el;
  }

  private resetLayers(night: boolean) {
    this.$bgDay.style.filter = this.$bgNight.style.filter = "none";
    this.$sun.style.filter   = this.$moon.style.filter   = "none";
    // In transparent mode: white clouds with shadow so they show on any background
    this.$clouds.style.filter = this.isTransparent
      ? "drop-shadow(0 4px 12px rgba(0,0,0,0.18)) brightness(1.05)"
      : (night
          ? "brightness(0.25) drop-shadow(0 0 10px rgba(255,255,255,1))"
          : "brightness(1.2) drop-shadow(0 0 10px rgba(255,255,255,1))");
    this.$fogHaze.style.opacity = "0";
    this.$flash.style.opacity   = "0";
    this.$stars.style.opacity   = "0";
    for (const el of [this.$rain, this.$snow, this.$hail, this.$wind]) {
      el.innerHTML = ""; el.style.opacity = "0";
    }
    this.$thunder.style.opacity = "0";
  }

  private applyState() {
    this.clearTimers();
    const cond  = this.normalizeCondition(this.condition);
    const night = this.forcedNight !== null ? this.forcedNight :
                  (cond === "clear-night" || this.isNightByClock());
    const p = PROFILES[cond] ?? PROFILES.cloudy;
    const transparent = this.isTransparent;
    const coloredBg   = this.isColoredBg;

    // Colored-bg off: hide sky gradient entirely (pure glass)
    // Transparent mode: semi-transparent sky (wallpaper shows through)
    this.$bgDay.style.opacity   = !coloredBg ? "0" : transparent ? (night ? "0" : "0.38") : (night ? "0" : "1");
    this.$bgNight.style.opacity = !coloredBg ? "0" : transparent ? (night ? "0.45" : "0") : (night ? "1" : "0");
    // Transparent mode: sun only for daytime conditions; moon+stars follow the same
    // rules as opaque mode so clear-night still shows moon and stars.
    const showSun  = transparent ? (!night && (p.showSun !== false)) : (p.showSun ?? !night);
    const showMoon = p.showMoon ?? night;   // same logic in both modes
    this.$sun.style.display  = "";
    this.$moon.style.display = "";
    this.$stars.style.display = night ? "block" : "none";  // stars whenever it's night
    this.$sun.style.transform  = `rotate(${night ?  96 :  14}deg)`;
    this.$moon.style.transform = `rotate(${night ?  18 : -96}deg)`;
    this.resetLayers(night);

    this.$sun.style.opacity  = String(showSun  ? 1 : 0);
    this.$moon.style.opacity = String(showMoon ? 1 : 0);
    this.$clouds.style.opacity  = String(this.getVal(p, "cloudOpacity",   night, night ? .12 : .1));
    this.$fogHaze.style.opacity = String(this.getVal(p, "fogOpacity",     night, 0));
    this.$stars.style.opacity   = String(night ? this.getVal(p, "starsOpacity", night, .6) : 0);

    // Overlay mode: another layer already paints the sky, so everything that
    // draws one is switched off here and only the particles below remain — the
    // stars aside, which keep their profile strength (night only) and, in overlay
    // mode, sit in the upper sky band only (see renderStars).
    if (this.isOverlay) {
      this.$bgDay.style.opacity = this.$bgNight.style.opacity = "0";
      this.$sun.style.opacity = this.$moon.style.opacity = "0";
      this.$clouds.style.opacity = this.$fogHaze.style.opacity = "0";   // stars stay: they twinkle over the painted night sky
    }

    // Sun glow (overlay only): sunny by day at full strength, partly cloudy at about
    // half; never at night or under grey skies. Upper LEFT (the painted shadows fall to the right), its centre outside the tile.
    this.$sunglow.style.opacity = "0";
    if (this.isOverlay && !night && (cond === "sunny" || cond === "partlycloudy")) {
      const f = this.pictureFrame();
      const d = f.Hp * 1.5;                                    // diameter, follows the picture
      // The centre lies OUTSIDE the tile, above its top edge (the sun is meant to be out of frame, same for sunny and partly cloudy):
      // only the glow reaching into the sky is seen, never a disc or a hot centre.
      const cx = f.W * 0.2, cy = -d * 0.2;
      this.$sunglow.style.width = this.$sunglow.style.height = `${d.toFixed(0)}px`;
      this.$sunglow.style.left = `${(cx - d / 2).toFixed(0)}px`;
      this.$sunglow.style.top = `${(cy - d / 2).toFixed(0)}px`;
      this.$sunglow.style.opacity = "1";
    }

    // Rays and motes (overlay, sunny by day only).
    this.$sunrays.style.opacity = this.$motes.style.opacity = "0";
    if (this.isOverlay && !night && cond === "sunny") {
      const f = this.pictureFrame();
      const sx = f.W * 0.2, sy = -f.Hp * 0.3;                  // the source: off-tile, upper left
      const reach = Math.hypot(f.W, f.H) * 1.15;
      if (this.$sunrays.dataset.k !== `${Math.round(f.W / 8)}x${Math.round(f.H / 8)}`) {
        this.$sunrays.dataset.k = `${Math.round(f.W / 8)}x${Math.round(f.H / 8)}`;
        this.$sunrays.innerHTML = "";
        // A fan of soft, wide beams from the source, angled down-right across the sky.
        const beams = [ { rot: -38, w: 0.075, a: .11 }, { rot: -26, w: 0.05, a: .15 }, { rot: -14, w: 0.09, a: .1 }, { rot: -3, w: 0.045, a: .13 }, { rot: 9, w: 0.07, a: .09 }, { rot: 22, w: 0.05, a: .08 } ];
        beams.forEach((b, i) => {
          const el = document.createElement("span");
          el.className = "sunray";
          const wpx = f.Hp * b.w * 1.6;
          el.style.width = `${wpx.toFixed(0)}px`;
          el.style.height = `${reach.toFixed(0)}px`;
          el.style.left = `${(sx - wpx / 2).toFixed(0)}px`;
          el.style.top = `${sy.toFixed(0)}px`;
          el.style.setProperty("--rot", `${b.rot}deg`);
          el.style.setProperty("--ra", `${b.a}`);
          el.style.setProperty("--rlo", `${0.25 + 0.15 * ((i * 0.37) % 1)}`);
          el.style.transform = `rotate(${b.rot}deg)`;
          el.style.animationDuration = `${(11 + 5 * ((i * 0.61) % 1)).toFixed(1)}s`;
          el.style.animationDelay = `-${(i * 2.3).toFixed(1)}s`;
          this.$sunrays.appendChild(el);
        });
        // Motes: small, pale, mostly over the sky and the trees, thinning out over the meadow, drifting up and to the right.
        this.$motes.innerHTML = "";
        const n = 26;
        for (let m = 0; m < n; m++) {
          const el = document.createElement("span");
          el.className = "mote";
          const sz = 1.4 + 2.0 * Math.random();
          el.style.width = el.style.height = `${sz.toFixed(1)}px`;
          el.style.left = `${(f.W * Math.random()).toFixed(0)}px`;
          // Spread from the sky down over the meadow: pale specks only read against the
          // blue and the dark trees, so most start in the upper and middle band.
          el.style.top = `${(f.H * (0.12 + 0.7 * Math.pow(Math.random(), 1.4))).toFixed(0)}px`;
          el.style.setProperty("--mx", `${(f.W * (0.06 + 0.1 * Math.random())).toFixed(0)}px`);
          el.style.setProperty("--my", `${(-f.H * (0.14 + 0.2 * Math.random())).toFixed(0)}px`);
          el.style.setProperty("--mo", `${(0.55 + 0.4 * Math.random()).toFixed(2)}`);
          const dur = 16 + 16 * Math.random();
          el.style.animationDuration = `${dur.toFixed(1)}s`;
          el.style.animationDelay = `-${(dur * Math.random()).toFixed(1)}s`;
          this.$motes.appendChild(el);
        }
      }
      this.$sunrays.style.opacity = "1";
      this.$motes.style.opacity = "1";
    }

    // Stars: inside the sky of the picture (its top ~36 %), wherever that lies in the tile.
    if (this.isOverlay) {
      const f = this.pictureFrame();
      const top = Math.max(0, f.off), span = Math.max(8, f.off + f.Hp * 0.36 - top);
      this.$stars.querySelectorAll<HTMLElement>(".star").forEach((el) => {
        el.style.top = `${(top + span * Number(el.dataset.r ?? 0.5)).toFixed(0)}px`;
      });
    }

    const dayFilter    = this.getStr(p, "dayFilter",   night);
    const cloudFilter  = this.getStr(p, "cloudFilter", night);
    if (dayFilter)   this.$bgDay.style.filter    = dayFilter;
    if (cloudFilter) this.$clouds.style.filter   = cloudFilter;

    // Overlay mode, drifting clouds: only for the grey, overcast looks and only by
    // day (a pale cloud texture on a painted night sky looks pasted on). They
    // lighten the painted sky with a `screen` blend rather than sitting on it as
    // an opaque texture, at ~60 % of the standalone strength: a first try at a
    // quarter strength, in plain grey, was invisible against an already grey
    // sky. Masked to the upper sky band so no cloud floats over the meadow.
    if (this.isOverlay) {
      // partlycloudy is drawn on a CLEAR blue sky (the widget swaps in the clear
      // picture for that look), where white clouds have contrast and show as
      // motion: normal blend, near full strength, with a soft glow. The grey
      // looks lighten the painted sky with a screen blend instead — white over
      // the already-white clouds of a painted partlycloudy sky was invisible.
      const partly = cond === "partlycloudy";
      const rainy = cond === "rainy" || cond === "pouring" || cond === "hail";   // not lightning-rainy: the storm picture has its own dark clouds
      const flat = cond === "cloudy" || cond === "windy-variant" || rainy;   // a flat grey painted sky
      const drifts = partly || flat;
      // A flat grey sky (the clean cloudy picture, also the base for rain) has no structure
      // of its own, so the drifting texture is laid on in a normal blend — a screen blend
      // at ~60 % was barely visible there. Rain gets it dimmer and greyer.
      // Two containers with the balloon's slot between them: the back cloud layer, the
      // balloon (light DOM, slot="mid"), then the front cloud layer — so the balloon
      // floats between the clouds. Both containers get the same look.
      const front = this.ensureFrontClouds();
      const cOpacity = drifts && !night ? (partly ? "0.9" : rainy ? "0.5" : "0.8") : "0";
      const cFilter = partly ? "brightness(1.15) drop-shadow(0 0 10px rgba(255,255,255,.8))" : rainy ? "brightness(0.85)" : "brightness(1.15)";
      for (const el of [this.$clouds, front]) { el.style.opacity = cOpacity; el.style.filter = cFilter; el.style.mixBlendMode = "normal"; }
      // Overlay clouds: more of them, smaller, higher and slower than the standalone
      // widget's three (26/33/41 s per crossing). The sky band of a landscape picture
      // is narrow, so three slow big ones left long empty gaps; five, evenly staggered
      // along the whole path by negative delays, keep a few in view at all times.
      const f = this.pictureFrame();
      const key = `${Math.round(f.W / 8)}x${Math.round(f.H / 8)}`;
      if (this.$clouds.dataset.ov !== key) {
        this.$clouds.dataset.ov = key;
        this.$clouds.innerHTML = ""; front.innerHTML = "";
        // Two depth layers. Back: smaller, paler, softly blurred, higher and slower;
        // front: larger, brighter, a bit faster and lower in the sky band. The speed
        // difference is what reads as depth (parallax). Each layer is its own
        // container so the back one can be blurred and dimmed as a whole.
        const layers: Array<{ n: number; h: number[]; top?: number[]; tgt?: number[]; dur: number[]; op: number; blur: string }> = [
          { n: 6, h: [0.5, 0.8],   tgt: [0.03, 0.2], dur: [255, 345], op: 0.75, blur: "blur(1.8px) brightness(0.96)" },   // back: small, pale, soft, slow
          { n: 3, h: [1.0, 1.6],   top: [-0.7, -0.42],  dur: [104, 140],   op: 1,    blur: "drop-shadow(0 0 10px rgba(255,255,255,.7)) brightness(1.08)" },   // front: large, bright, crisp, fast
        ];
        layers.forEach((L, li) => {
          const box = document.createElement("div");
          box.style.cssText = `position:absolute;inset:0;opacity:${L.op};filter:${L.blur};`;
          for (let i = 0; i < L.n; i++) {
            const img = document.createElement("img");
            img.className = "cloud-img";
            img.alt = "";
            img.src = this.cloudSrc;
            img.onerror = () => { const fb = this.getCanvasSrc(); if (img.src !== fb) img.src = fb; };
            // Height is a share of the PICTURE height, width follows the texture (320x307).
            const hc = f.Hp * (L.h[0] + (L.h[1] - L.h[0]) * Math.random());
            const wc = hc * (320 / 307);
            const dur = L.dur[0] + (L.dur[1] - L.dur[0]) * Math.random();
            img.style.width = `${wc.toFixed(0)}px`;
            img.style.left = `${(-wc).toFixed(0)}px`;                       // starts fully off the left edge
            const u = (i * 0.618 + li * 0.31) % 1;
            // The cloud texture sits about 65 % down its own image, so a small cloud has
            // to be placed by where that TEXTURE should land in the sky (`tgt`, as a share
            // of the picture height), not by the image's top edge (`top`).
            const tf = L.tgt ? L.tgt[0] + (L.tgt[1] - L.tgt[0]) * u - 0.65 * (hc / f.Hp)
                             : L.top![0] + (L.top![1] - L.top![0]) * u;
            img.style.top = `${(f.off + f.Hp * tf).toFixed(0)}px`;          // upper sky of the picture
            img.style.setProperty("--tx", `${(((f.W + wc) / wc) * 100).toFixed(0)}%`);   // ...ends fully off the right edge
            img.style.animation = `cloud-ov ${dur.toFixed(0)}s linear infinite`;
            img.style.animationDelay = `-${(dur * (i + 0.5 * li) / L.n).toFixed(1)}s`;   // even stagger along the path
            box.appendChild(img);
          }
          (li === 0 ? this.$clouds : front).appendChild(box);
        });
      }

      const y0 = Math.max(0, f.off + f.Hp * 0.215), y1 = Math.max(y0 + 1, f.off + f.Hp * 0.36);
      const mask = `linear-gradient(to bottom,#000 0,#000 ${y0.toFixed(0)}px,transparent ${y1.toFixed(0)}px)`;
      for (const el of [this.$clouds, front]) { el.style.setProperty("-webkit-mask-image", mask); el.style.setProperty("mask-image", mask); }
    }


    const rain   = this.getVal(p, "rainCount",   night, 0);
    const snow   = this.getVal(p, "snowCount",   night, 0);
    const hail   = this.getVal(p, "hailCount",   night, 0);
    const leaves = this.getVal(p, "leavesCount", night, 0);

    // Overlay hail comes with the rain streaks around it, as in a real shower.
    if (this.isOverlay && cond === "hail") { this.spawnRain(70); this.$rain.style.opacity = "1"; }
    if (rain   > 0) { this.spawnRain(rain);   this.$rain.style.opacity   = "1"; }
    if (snow   > 0) { this.spawnSnow(snow);   this.$snow.style.opacity   = "1"; }
    if (hail   > 0) { this.spawnHail(hail);   this.$hail.style.opacity   = "1"; }
    if (leaves > 0) { this.spawnLeaves(leaves); this.$wind.style.opacity = "1"; }

    // Overlay mode runs everything slower than the standalone widget: a painted
    // landscape calls for calmer movement (rain is left as tuned).
    if (this.isOverlay) {
      const slow = (root: HTMLElement, sel: string, k: number) => root.querySelectorAll<HTMLElement>(sel).forEach((el) => {
        el.style.animationDuration = `${((parseFloat(el.style.animationDuration) || 3) * k).toFixed(2)}s`;
      });
      slow(this.$wind, ".leaf", 1.6);
    }

    if (p.thunder) {
      this.$thunder.style.opacity = "1";
      this.$sun.style.filter  = "grayscale(0.95)";
      this.$moon.style.filter = "brightness(0.82)";
      this.startLightning();
    }
  }

  private spawnRain(count: number) {
    const frag = document.createDocumentFragment();
    if (this.isOverlay) {
      const H = this.clientHeight || 300;
      const rot = 7;                                   // degrees off vertical
      const dx = Math.tan(rot * Math.PI / 180) * H * 1.45;  // sideways travel over the 145% fall
      // tier: share of drops, length (fraction of H), width, alpha, fall time
      const tiers = [
        { share: 0.05, len: 0.26, w: 1.5, a: 0.5,  o: 1,   t: [0.55, 0.8] },  // near
        { share: 0.25, len: 0.11, w: 1.2, a: 0.32, o: 0.9, t: [0.75, 1.0] },  // mid
        { share: 0.70, len: 0.05, w: 1.0, a: 0.2,  o: 0.8, t: [1.0, 1.4] },   // far
      ];
      // Real layers, one per tier: each its own container so the far one can be
      // softened as a whole (one blur, not one per drop) and stack behind the rest.
      const blur = ["none", "blur(0.3px)", "blur(0.7px)"];
      const layers = tiers.map((_, k) => {
        const d = document.createElement("div");
        d.style.cssText = `position:absolute;inset:0;overflow:hidden;filter:${blur[k]};`;
        return d;
      });
      for (let i = 0; i < count; i++) {
        const r = i / count;
        const k = r < tiers[0].share ? 0 : r < tiers[0].share + tiers[1].share ? 1 : 2;
        const tier = tiers[k];
        const el = document.createElement("span");
        el.className = "rdrop";
        el.style.setProperty("--h", `${(H * tier.len * (0.8 + 0.4 * Math.random())).toFixed(1)}px`);
        el.style.setProperty("--w", `${tier.w}px`);
        el.style.setProperty("--a", `${tier.a}`);
        el.style.setProperty("--o", `${tier.o}`);
        el.style.setProperty("--rot", `${rot}deg`);
        el.style.setProperty("--dx", `${dx.toFixed(1)}px`);
        // The start x reaches past the right edge: the slant carries every drop left.
        el.style.setProperty("--x", `${(-2 + 112 * Math.random()).toFixed(1)}%`);
        const dur = tier.t[0] + (tier.t[1] - tier.t[0]) * Math.random();
        el.style.animationDuration = `${dur.toFixed(2)}s`;
        // Negative delay: every drop starts already mid-fall.
        el.style.animationDelay = `-${(dur * Math.random()).toFixed(2)}s`;
        layers[k].appendChild(el);
      }
      // Far first, near last, so the long bright streaks sit in front.
      for (const l of [layers[2], layers[1], layers[0]]) frag.appendChild(l);
      this.$rain.appendChild(frag);
      return;
    }
    for (let i = 0; i < count; i++) {
      const el = document.createElement("span");
      el.className = "drop";
      el.style.left = `${100 * Math.random()}%`;
      el.style.animationDuration = `${0.95 + 0.65 * Math.random()}s`;
      el.style.animationDelay    = `${1.2  * Math.random()}s`;
      el.style.opacity = `${0.52 + 0.3 * Math.random()}`;
      frag.appendChild(el);
    }
    this.$rain.appendChild(frag);
  }

  private spawnSnow(count: number) {
    const frag = document.createDocumentFragment();
    if (this.isOverlay) {
      // Big soft out-of-focus dots in front, small sharper ones behind, and a few
      // six-armed crystals; a slow, calm fall with a slight sway to the right.
      const H = this.clientHeight || 300;
      const W = this.clientWidth || 300;
      // Sized by the shorter side: on a tall narrow tile the flakes are a lot bigger relative to it
      // than on a wide one, so they shrink there.
      const k = Math.min(1, Math.max(0.5, Math.min(H, W * 1.15) / 300)) * (H > W * 1.15 ? 0.65 : 1);
      const n = Math.round(count * 1.8);
      for (let i = 0; i < n; i++) {
        const r = Math.random();
        const crystal = r < 0.09;
        const depth = Math.random();                 // 0 = far, 1 = near
        const el = document.createElement("span");
        el.className = crystal ? "flake fc" : "flake fb";
        const size = (crystal ? 9 + 6 * depth : 2.5 + 11 * depth * depth) * k;
        el.style.setProperty("--x", `${(-2 + 104 * Math.random()).toFixed(1)}%`);
        el.style.width = el.style.height = `${size.toFixed(1)}px`;
        if (!crystal && depth > 0.55) el.style.filter = `blur(${(0.6 + 1.4 * (depth - 0.55)).toFixed(1)}px)`;
        if (crystal) {
          el.innerHTML = '<svg viewBox="-10 -10 20 20" width="100%" height="100%" fill="none" stroke="rgba(255,255,255,.95)" stroke-width="1.3" stroke-linecap="round"><path d="M0-9V9M-7.8-4.5 7.8 4.5M-7.8 4.5 7.8-4.5M0-9l-2.2 2.2M0-9l2.2 2.2M0 9l-2.2-2.2M0 9l2.2-2.2"/></svg>';
        }
        const dur = 7.5 - 2.5 * depth + 2.5 * Math.random();   // near flakes fall a bit faster
        const swd = 3 + 2.5 * Math.random();               // one slow sway, back and forth
        el.style.animationDuration = `${dur.toFixed(2)}s, ${swd.toFixed(2)}s`;
        el.style.animationDelay = `-${(dur * Math.random()).toFixed(2)}s, -${(swd * Math.random()).toFixed(2)}s`;
        el.style.opacity = `${(0.6 + 0.4 * depth).toFixed(2)}`;
        el.style.setProperty("--x-drift", `${(8 + 24 * Math.random()).toFixed(1)}px`);
        el.style.setProperty("--sw", `${((Math.random() < 0.5 ? -1 : 1) * (6 + 12 * (0.4 + depth) * Math.random()) * k).toFixed(1)}px`);
        frag.appendChild(el);
      }
      this.$snow.appendChild(frag);
      return;
    }
    for (let i = 0; i < count; i++) {
      const el = document.createElement("span");
      const size = 2 + 4 * Math.random();
      el.className = "flake";
      el.style.left   = `${100 * Math.random()}%`;
      el.style.width  = el.style.height = `${size}px`;
      el.style.animationDuration = `${2 + 2.2 * Math.random()}s`;
      el.style.animationDelay    = `${2.5 * Math.random()}s`;
      el.style.opacity = `${0.4 + 0.58 * Math.random()}`;
      el.style.setProperty("--x-drift", `${20 * Math.random() - 10}px`);
      frag.appendChild(el);
    }
    this.$snow.appendChild(frag);
  }

  private spawnHail(count: number) {
    const frag = document.createDocumentFragment();
    if (this.isOverlay) {
      // Translucent glassy beads of three sizes/depths on the rain's slant: far = small + blurred,
      // near = large + slightly soft. Fewer than the standalone widget.
      const H = this.clientHeight || 300;
      const k = Math.min(1.1, Math.max(0.7, H / 400));
      const drift = -Math.tan(7 * Math.PI / 180) * H * 1.28;
      const tiers = [
        { share: 0.2, s: [5, 7], blur: "blur(0.6px)", t: [0.6, 0.85] },
        { share: 0.4, s: [3, 4.5],  blur: "none",        t: [0.75, 1.05] },
        { share: 0.4, s: [1.8, 2.8], blur: "blur(0.7px)", t: [0.95, 1.3] },
      ];
      const n = Math.round(count * 0.5);
      for (let i = 0; i < n; i++) {
        const r = i / n;
        const tier = r < tiers[0].share ? tiers[0] : r < tiers[0].share + tiers[1].share ? tiers[1] : tiers[2];
        const el = document.createElement("span");
        const size = (tier.s[0] + (tier.s[1] - tier.s[0]) * Math.random()) * k;
        el.className = "hailstone hb";
        el.style.left = `${-2 + 106 * Math.random()}%`;
        el.style.width = el.style.height = `${size.toFixed(1)}px`;
        el.style.filter = tier.blur;
        const dur = tier.t[0] + (tier.t[1] - tier.t[0]) * Math.random();
        el.style.animationDuration = `${dur.toFixed(2)}s`;
        el.style.animationDelay = `-${(dur * Math.random()).toFixed(2)}s`;
        el.style.opacity = "0.9";
        el.style.setProperty("--x-drift", `${drift.toFixed(1)}px`);
        frag.appendChild(el);
      }
      this.$hail.appendChild(frag);
      return;
    }
    for (let i = 0; i < count; i++) {
      const el = document.createElement("span");
      const size = 2.5 + 2.8 * Math.random();
      el.className = "hailstone";
      el.style.left   = `${100 * Math.random()}%`;
      el.style.width  = el.style.height = `${size}px`;
      el.style.animationDuration = `${0.55 + 0.35 * Math.random()}s`;
      el.style.animationDelay    = `${1.1  * Math.random()}s`;
      el.style.opacity = `${0.55 + 0.4 * Math.random()}`;
      // Overlay: same right-to-left slant as the rain (7° off vertical over the 128% fall).
      const drift = this.isOverlay ? -Math.tan(7 * Math.PI / 180) * this.clientHeight * 1.28 : 10 + 24 * Math.random();
      el.style.setProperty("--x-drift", `${drift.toFixed(1)}px`);
      frag.appendChild(el);
    }
    this.$hail.appendChild(frag);
  }

  private spawnLeaves(count: number) {
    const frag = document.createDocumentFragment();
    for (let i = 0; i < count; i++) {
      const el = document.createElement("span");
      const w = 7 + 8 * Math.random();
      el.className = "leaf";
      el.style.width  = `${w}px`;
      el.style.height = `${Math.max(5, 0.62 * w)}px`;
      el.style.setProperty("--leaf-top",     `${12 + 70 * Math.random()}%`);
      el.style.setProperty("--leaf-rise",    `${-10 - 24 * Math.random()}px`);
      el.style.setProperty("--leaf-fall",    `${8  + 22 * Math.random()}px`);
      el.style.setProperty("--leaf-opacity", `${0.5 + 0.45 * Math.random()}`);
      el.style.animationDuration = `${2.2 + 2.6 * Math.random()}s`;
      el.style.animationDelay    = `${2.2 * Math.random()}s`;
      frag.appendChild(el);
    }
    this.$wind.appendChild(frag);
  }

  // Overlay mode: a jagged bolt with side branches, drawn in the picture's own
  // coordinates (1000 x 464) from the cloud base down to the horizon, in the look
  // of the painted one: a hot white core, a blue-white body and a wide soft glow.
  private strikeBolt(): number {
    const NS = "http://www.w3.org/2000/svg";
    let svg = this.$thunder.querySelector<SVGSVGElement>("svg.bolt");
    if (!svg) {
      svg = document.createElementNS(NS, "svg") as SVGSVGElement;
      svg.setAttribute("class", "bolt");
      svg.setAttribute("viewBox", "0 0 1000 464");
      svg.setAttribute("preserveAspectRatio", "none");
      svg.style.cssText = "position:absolute;overflow:visible;pointer-events:none;opacity:0;";
      this.$thunder.appendChild(svg);
    }
    const f = this.pictureFrame();
    const Wp = f.Hp / 0.464;
    svg.style.left = `${(f.W - Wp) / 2}px`; svg.style.top = `${f.off}px`;
    svg.style.width = `${Wp}px`; svg.style.height = `${f.Hp}px`;

    const jag = (x0: number, y0: number, x1: number, y1: number, step: number, amp: number) => {
      const pts: Array<[number, number]> = [[x0, y0]];
      const n = Math.max(3, Math.round(Math.hypot(x1 - x0, y1 - y0) / step));
      for (let i = 1; i < n; i++) {
        const t = i / n;
        pts.push([x0 + (x1 - x0) * t + (Math.random() - 0.5) * 2 * amp, y0 + (y1 - y0) * t + (Math.random() - 0.5) * amp * 0.5]);
      }
      pts.push([x1, y1]);
      return pts;
    };
    const d = (pts: Array<[number, number]>) => "M" + pts.map((q) => `${q[0].toFixed(1)} ${q[1].toFixed(1)}`).join("L");

    const x0 = 330 + 340 * Math.random(), y0 = 88 + 10 * Math.random();
    const x1 = x0 + (Math.random() - 0.5) * 120, y1 = 215 + 30 * Math.random();
    const main = jag(x0, y0, x1, y1, 16, 13);
    let paths = [{ d: d(main), w: 1 }];
    // Two or three branches leave the main stroke going sideways and down.
    const nb = 2 + Math.floor(Math.random() * 2);
    for (let b = 0; b < nb; b++) {
      const at = main[1 + Math.floor(Math.random() * (main.length - 3))];
      const dir = Math.random() < 0.5 ? -1 : 1;
      const len = 50 + 90 * Math.random();
      paths.push({ d: d(jag(at[0], at[1], at[0] + dir * len, at[1] + len * (0.25 + 0.4 * Math.random()), 12, 8)), w: 0.6 });
    }
    svg.innerHTML = "";
    const layer = (w: number, color: string, blur: string) => {
      const g = document.createElementNS(NS, "g");
      g.setAttribute("fill", "none"); g.setAttribute("stroke", color); g.setAttribute("stroke-linecap", "round"); g.setAttribute("stroke-linejoin", "round");
      if (blur) g.setAttribute("style", `filter:${blur}`);
      for (const pth of paths) {
        const e = document.createElementNS(NS, "path");
        e.setAttribute("d", pth.d);
        e.setAttribute("stroke-width", (w * pth.w).toFixed(2));
        g.appendChild(e);
      }
      svg!.appendChild(g);
    };
    // Wide pale halo where the bolt leaves the cloud (it lights the clouds around it) ...
    const glow = document.createElementNS(NS, "ellipse");
    glow.setAttribute("cx", x0.toFixed(1)); glow.setAttribute("cy", (y0 + 25).toFixed(1));
    glow.setAttribute("rx", "70"); glow.setAttribute("ry", "45");
    glow.setAttribute("fill", "rgba(235,238,255,.16)"); glow.setAttribute("style", "filter:blur(22px)");
    svg.appendChild(glow);
    // ... then halo along the whole bolt, nearly white with only a trace of lavender.
    layer(26, "rgba(225,232,255,.26)", "blur(10px)");
    layer(9, "rgba(232,238,255,.5)", "blur(3.5px)");
    layer(3, "rgba(246,248,255,.97)", "blur(0.5px)");
    layer(1.3, "#ffffff", "");
    svg.style.opacity = "1";
    setTimeout(() => { if (svg) svg.style.opacity = "0"; }, 90);
    setTimeout(() => {
      if (!svg) return;
      svg.style.opacity = "0.75";
      setTimeout(() => { if (svg) svg.style.opacity = "0"; }, 70);
    }, 140);
    return x0 / 1000;
  }

  private startLightning() {
    if (this.isPaused) return;
    const flash = () => {
      if (this.isOverlay) this.strikeBolt();
      this.$flash.style.opacity = "0.95";
      setTimeout(() => { this.$flash.style.opacity = "0"; }, 80);
      setTimeout(() => {
        this.$flash.style.opacity = "0.65";
        setTimeout(() => { this.$flash.style.opacity = "0"; }, 65);
      }, 120);
      this._flashTimer = setTimeout(flash, 1000 + 3600 * Math.random());
    };
    this._flashTimer = setTimeout(flash, 450 + 800 * Math.random());
  }
}

if (!customElements.get("weather-bg")) {
  customElements.define("weather-bg", WeatherBgElement as unknown as CustomElementConstructor);
}
